def _custom(self, *sequences: str) -> str:
    short = min(sequences, key=len)
    length = len(short)
    for n in range(length, 0, -1):
        for subseq in find_ngrams(short, n):
            joined = ''.join(subseq)
            for seq in sequences:
                if joined not in seq:
                    break
            else:
                return joined
    return type(short)()  # empty sequence
